package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import java.io.*;
public class QueueDownloadChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String s){if(!ok)throw new AssertionError(s);}interface Condition{boolean ready();}void waitFor(Condition c,int seconds)throws Exception{for(int n=0;n<seconds*10;n++){if(c.ready())return;Thread.sleep(100);}throw new Exception("Timed out");}
 public void onStart(){Bundle result=new Bundle();PlaybackService service=null;ArrayList<Track> saved=null,next=null;int old=0;boolean repeat=false;try{startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->PlaybackService.instance!=null,10);service=PlaybackService.instance;final PlaybackService p=service;saved=new ArrayList<>(p.queue);next=new ArrayList<>(p.upcoming);old=p.index;repeat=p.repeat;runOnMainSync(()->{p.pause(true);p.releasePlayer();p.upcoming.clear();p.queue.clear();p.index=0;p.repeat=true;p.queue.add(new Track("Background test","Original demo","demo","local"));p.queue.add(new Track("Download fixture","Public test","DTi8wZ1a1TA","youtube"));AudioCache.remove(getTargetContext(),"DTi8wZ1a1TA");p.queueChanged();p.play(0);});waitFor(()->p.playing(),10);runOnMainSync(()->p.enqueue(p.queue.get(1),false));waitFor(()->AudioCache.find(getTargetContext(),"DTi8wZ1a1TA")!=null,180);check(p.index==0&&p.playing(),"Prefetch interrupted current track");runOnMainSync(()->{p.repeat=false;p.refreshUpcoming();});waitFor(()->p.nextPrepared,10);check(p.upcoming.size()==1,"Prefetch consumed queue entry");runOnMainSync(()->p.removeTrack(p.queue.get(1)));check(AudioCache.find(getTargetContext(),"DTi8wZ1a1TA")==null,"Delete did not remove cached fixture");Thread.sleep(1000);check(p.playing()&&p.index==0&&p.upcoming.isEmpty(),"Delete changed current playback");result.putString("result","PASS: actual background audio download, uninterrupted current playback, prepared next player, queue retained until playback, cache deletion");}catch(Throwable e){result.putString("failure",e.toString());}finally{if(service!=null&&saved!=null){final PlaybackService p=service;final ArrayList<Track> library=saved,upcoming=next;final int at=old;final boolean r=repeat;runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.queue.addAll(library);p.upcoming.clear();p.upcoming.addAll(upcoming);p.index=at;p.repeat=r;p.save();});}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}}
}
